from gen import *
C=[]
def orow(n,sub,side,q,st,k): return f'<div class="row" style="padding:14px 0;border-top:1px solid var(--line)"><div><b style="font-size:15px">{n}</b><div class="sub" style="margin-top:3px">{side} · {q} · {sub}</div></div>{pill(st,k)}</div>'
tabs=lambda on:'<div class="seg" style="margin:6px 0 10px">'+''.join(f'<span class="{"on" if t==on else ""}">{t}</span>' for t in ["Open","Executed","GTT"])+'</div>'
C.append(phone("C1 · ORDERS · OPEN", pad('<div class="row" style="height:52px"><div class="h1" style="font-size:26px">Orders</div></div>'+tabs("Open")+orow("TCS","Limit ₹3,410","Buy","12 qty","Waiting","wait")+orow("Suzlon","Limit ₹46.50","Buy","500 qty","Waiting","wait")+orow("HDFC Bank","Market","Sell","4 qty","Partial 2/4","wait"),'padding-bottom:90px'),"ord"))
C.append(phone("C2 · ORDERS · EXECUTED", pad('<div class="row" style="height:52px"><div class="h1" style="font-size:26px">Orders</div></div>'+tabs("Executed")+orow("Reliance","₹1,209.73","Buy","22 qty","Executed","up")+orow("Canara Bank","₹110.14","Buy","148 qty","Executed","up")+orow("Vodafone Idea","Limit ₹13.80","Buy","1000 qty","Rejected","dn")+orow("Infosys","₹1,860.00","Sell","6 qty","Executed","up"),'padding-bottom:90px'),"ord"))
C.append(phone("C3 · ORDERS · GTT", pad('<div class="row" style="height:52px"><div class="h1" style="font-size:26px">Orders</div></div>'+tabs("GTT")+card('<div class="row"><b>HDFC Bank · Sell</b>'+pill("Active","up")+'</div><div class="sub" style="margin:4px 0 10px">Good till triggered · expires 12 months</div>'+kv("Trigger","₹1,740.00",True)+kv("Sell qty","8",True)+kv("Current price","₹1,652.00",True))+'<div style="height:12px"></div>'+card('<div class="row"><b>Suzlon · Buy</b>'+pill("Active","up")+'</div><div class="sub" style="margin:4px 0 10px">OCO: stop-loss + target</div>'+kv("Target","₹56.00",True)+kv("Stop-loss","₹44.00",True))+'<div class="mut" style="font-size:12px;margin-top:12px">GTT orders stay active until they trigger, so you don\'t need to place them again each day.</div>')+bottom(btn("+ Create GTT","lime"))))
C.append(phone("C4 · ORDER DETAIL", top("Order detail")+pad('<div style="text-align:center;margin-top:6px"><div class="sub">Buy · Delivery</div><div class="h1" style="font-size:24px;margin:6px 0">Reliance Industries</div>'+pill("Executed","up")+'</div>'+card(kv("Quantity","22 / 22",True)+kv("Average price","₹1,209.73",True)+kv("Order type","Limit",True)+kv("Order ID","240912000281",True),'margin-top:18px;padding:6px 18px')+'<div class="lbl" style="margin:18px 0 8px">TIMELINE</div>'+''.join(f'<div class="row" style="padding:8px 0;justify-content:flex-start;gap:12px"><span style="width:22px;height:22px;border-radius:50%;background:var(--lime);display:grid;place-items:center;font-size:12px">✓</span><div style="flex:1" class="row"><span style="font-size:14px">{a}</span><span class="sub num">{b}</span></div></div>' for a,b in [("Order placed","10:02:11"),("Sent to exchange","10:02:12"),("Executed","10:02:14")])+card(kv("Brokerage","₹0.00",True)+kv("STT + taxes","₹27.10",True),'margin-top:12px;padding:4px 18px'))+bottom(btn("Download contract note","ghost"))))
C.append(phone("C5 · MODIFY ORDER", top("Modify order")+pad('<div class="row"><div style="display:flex;gap:12px;align-items:center">'+logo("TC","#2F6FE0")+'<div><b>TCS · Buy</b><div class="sub">Limit order · waiting</div></div></div>'+pill("Waiting","wait")+'</div>'+'<div style="margin-top:18px">'+field("Quantity","12 → 15")+field("Limit price","₹3,410.00 → ₹3,405.00")+'</div>'+card(kv("Extra amount needed","₹10,215.00",True)+kv("Available","₹52,310.40",True),'padding:6px 18px')+'<div class="banner" style="background:var(--warnBg);color:var(--warn);margin-top:14px">Changing the price puts you at the back of the queue at that price.</div>')+bottom(btn("Confirm changes"),btn("Cancel order","ghost"))))
C.append(phone("C6 · ORDER REJECTED", pad('<div style="text-align:center;margin-top:50px"><div style="width:96px;height:96px;margin:0 auto;border-radius:50%;background:var(--dnBg);display:grid;place-items:center"><div style="width:60px;height:60px;border-radius:50%;background:var(--dn);display:grid;place-items:center;color:#fff;font-size:30px">×</div></div>'+h1("Order not placed",26).replace('class="h1"','class="h1" style="margin-top:22px"')+'<div class="mut" style="margin:8px 18px 0;font-size:14px">The exchange rejected this order. You haven\'t been charged.</div></div>'+card('<div class="lbl">REASON</div><div style="margin-top:6px;font-weight:600">Price is outside the allowed range for today</div><div class="mut" style="font-size:13px;margin-top:6px;line-height:1.5">Vodafone Idea can move between ₹12.65 and ₹15.47 today. Your limit of ₹11.00 is below that.</div>','margin-top:26px')+'<div style="margin-top:12px">'+card(kv("Order","Buy 1000 · IDEA",False)+kv("Limit price","₹11.00",True),'padding:6px 18px')+'</div>')+bottom(btn("Edit price and retry","lime"),btn("Back to orders","ghost"))))
C.append(phone("C7 · SELL WITH HEDGE & CONDITIONS", top("Order")+pad('<div class="row"><div style="display:flex;gap:12px;align-items:center">'+logo("TC","#2F6FE0")+'<div><b style="font-size:18px">TCS</b><div class="sub">NSE</div></div></div><div class="num" style="font-size:17px">₹3,412.30</div></div><div class="seg" style="margin:16px 0"><span>Buy</span><span class="on" style="background:var(--dn)">Sell</span></div><div style="display:flex;gap:8px;margin-bottom:14px">'+chip("Delivery")+chip("Intraday",True)+chip("+ Hedge",True)+'</div>'+card('<div class="row"><span class="mut">Quantity</span><span class="num" style="font-size:24px">10</span></div><div class="sep" style="margin:12px 0"></div><div class="row"><span class="mut">Price</span><span class="num" style="font-size:24px">Market</span></div>')+'<div class="lbl" style="margin:18px 0 8px">CONDITIONS</div>'+card('<div class="row"><b style="font-size:14px">Stop-loss</b><span class="num">₹3,340.00</span></div><div class="sep" style="margin:10px 0"></div><div class="row"><b style="font-size:14px">Target</b><span class="num">₹3,520.00</span></div>','padding:14px 18px')+'<div class="row mut" style="margin:14px 4px 0;font-size:13px"><span>Margin with hedge</span><b class="num" style="color:var(--ink)">₹18,420.00</b></div>')+bottom('<div style="height:62px;border-radius:20px;background:var(--dn);position:relative;display:flex;align-items:center;justify-content:center;color:#fff;font-weight:600"><span style="position:absolute;left:6px;width:50px;height:50px;border-radius:15px;background:#fff;display:grid;place-items:center;color:var(--ink);font-size:20px">→</span>Swipe to sell</div>')))
sheet("flow-c-orders.html","Crestline — orders",C)
